"""Standard-library-only summaries. Block medians are never called pooled percentiles."""
from pathlib import Path
import csv
import json
import statistics
from collections import defaultdict

HERE = Path(__file__).resolve().parent
RUNS = [p for p in (HERE / 'run-3', HERE / 'run-4', HERE / 'run-5') if (p / 'frames.csv').exists()]
output = ['# Measurement tables', '',
          'Generated by summarize.py from run-3/4/5. Times are microseconds. '
          'Each CSV row is one block, not a pooled distribution. The baseline table uses the latest run. '
          'No percentage improvements are inferred from unpaired samples.', '']
summary = {}


def read(path):
    with path.open(newline='', encoding='utf-8') as f:
        return list(csv.DictReader(f))


def table(headers, rows):
    output.append('| ' + ' | '.join(headers) + ' |')
    output.append('| ' + ' | '.join(['---'] * len(headers)) + ' |')
    output.extend('| ' + ' | '.join(map(str, row)) + ' |' for row in rows)
    output.append('')


def number(r, key):
    return float(r[key])


def span(rows, key):
    values = [number(r, key) for r in rows]
    return f'{min(values):.1f}..{max(values):.1f}' if len(values) > 1 else f'{values[0]:.1f}'


for run in RUNS:
    data = {}
    parity = defaultdict(list)
    for row in read(run / 'parity.csv'):
        parity[(row['scope'], row['variant'])].append(row)
    data['parity'] = []
    for (scope, variant), rows in sorted(parity.items()):
        data['parity'].append(dict(scope=scope, variant=variant, cases=len(rows),
                                  different=sum(int(r['changed-pixels']) != 0 for r in rows),
                                  max_rgb=max(int(r['max-rgb']) for r in rows),
                                  max_alpha=max(int(r['max-alpha']) for r in rows),
                                  max_changed=max(int(r['changed-pixels']) for r in rows)))
    output += [f'## {run.name}: RGBA comparisons', '']
    table(['Scope', 'Variant', 'Cases', 'Different', 'Max RGB / alpha'],
          [(r['scope'], r['variant'], r['cases'], r['different'], f"{r['max_rgb']} / {r['max_alpha']}")
           for r in data['parity']])
    times = read(run / 'times.csv')
    output += [f'## {run.name}: paired ABBA, eleven full Conquer, P=64', '']
    rows = []
    for state in ('0', '2', '7'):
        for variant in ('skip', 'skip+java', 'skip+java+share', 'skip+vbo', 'skip+channels', 'skip+dual', 'skip+fetch'):
            base = [r for r in times if r['scope'] == 'ABBA' and r['state'] == state and r['groups'] == '11' and r['variant'] == 'stock-for-' + variant]
            candidate = [r for r in times if r['scope'] == 'ABBA' and r['state'] == state and r['groups'] == '11' and r['variant'] == variant]
            if base and candidate:
                rows.append((state, variant, span(base, 'median-us'), span(candidate, 'median-us'),
                             span(base, 'p95-us'), span(candidate, 'p95-us'),
                             span(base, 'completed-us-per-packet'), span(candidate, 'completed-us-per-packet')))
    table(['State', 'Variant', 'Stock p50 blocks', 'Candidate p50 blocks', 'Stock p95 blocks',
           'Candidate p95 blocks', 'Stock completed', 'Candidate completed'], rows)
    combo = defaultdict(list)
    for r in times:
        if r['scope'] == 'combination':
            combo[(r['state'], r['groups'], r['variant'])].append(r)
    if combo:
        output += [f'## {run.name}: 2x2 invisible-skip / dual-source', '']
        table(['State', 'Groups', 'Variant', 'p50 blocks', 'p95 blocks', 'Completed blocks'],
              [(state, n, v, span(rows, 'median-us'), span(rows, 'p95-us'), span(rows, 'completed-us-per-packet'))
               for (state, n, v), rows in sorted(combo.items())])
    if (run / 'queue.csv').exists():
        queue = defaultdict(list)
        for r in read(run / 'queue.csv'):
            queue[(r['pixels'], r['variant'], r['disjoint'], r['gl-draws'])].append(r)
        output += [f'## {run.name}: projection-only capture/replay', '']
        table(['P', 'Variant', 'Disjoint', 'Draws', 'p50 blocks', 'p95 blocks', 'Completed blocks'],
              [(p, v, disjoint, draws, span(rows, 'p50-us'), span(rows, 'p95-us'), span(rows, 'complete-us'))
               for (p, v, disjoint, draws), rows in sorted(queue.items(), key=lambda x: (int(x[0][0]), x[0][1]))])
    output += [f'## {run.name}: whole-client frame phases', '',
               'Modes: 0=HUD off; 1=basic; 2=full stock; 3=full skip; 4=full skip+dual. '
               'WARNING: mode 0 also changed native commandMode in these early runs; it is not a pure HUD-off control. '
               'The frame interval is DesktopLauncher.update CPU elapsed; no swap/presentation latency. '
               'Forward/reverse phase ranges, 120 frames per block after 50 warm frames.', '']
    frames = defaultdict(list)
    for r in read(run / 'frames.csv'):
        frames[(r['scene'], r['mode'])].append(r)
    table(['Units', 'Mode', 'Frame p50 blocks', 'Frame p95 blocks', 'Frame p99 blocks',
           'HUD p50 blocks', 'Over 8.33 / 16.67 ms'],
          [(scene, mode, span(rows, 'p50-frame-us'), span(rows, 'p95-frame-us'), span(rows, 'p99-frame-us'),
            span(rows, 'p50-hud-us'), f"{sum(int(r['over-8.33ms']) for r in rows)} / {sum(int(r['over-16.67ms']) for r in rows)}")
           for (scene, mode), rows in sorted(frames.items(), key=lambda x: (int(x[0][0]), int(x[0][1])))])
    summary[run.name] = data

latest = RUNS[-1]
times = read(latest / 'times.csv')
counts = read(latest / 'counts.csv')
gpu = read(latest / 'gpu-timers.csv')
output += [f'## {latest.name}: complete baseline matrix, P=64', '',
           'CPU columns are p50 / p95 / p99. GPU column is TIME_ELAPSED timeline p50; '
           'it is not an exclusive GPU busy counter. Texture/scissor are zero after warming for the isolated one-atlas fixture. '
           'noGL omits vertex construction and actual GL. B/packet is the timing-thread allocation counter.', '']
rows = []
for count in counts:
    if count['scope'] != 'isolated':
        continue
    matching = lambda r: all(r[k] == count[k] for k in ('type', 'state', 'groups', 'advanced')) and r['variant'] == 'stock'
    cpu = next(r for r in times if matching(r) and r['scope'] == 'isolated')
    java = next(r for r in times if matching(r) and r['scope'] == 'noGL')
    g = next((r for r in gpu if r['type'] == count['type'] and r['state'] == count['state'] and r['groups'] == count['groups'] and r['variant'] == 'stock'), None) if count['advanced'] == 'true' else None
    rows.append((count['type'], count['state'], count['groups'], count['advanced'],
                 java['median-us'], f"{cpu['median-us']} / {cpu['p95-us']} / {cpu['p99-us']}",
                 g['p50-us'] if g else 'not measured', count['quads'], count['flush-requests'], count['nonempty'],
                 count['blend-switches'], count['gl-texture-binds'], count['gl-scissors'], cpu['allocated-B-per-packet']))
table(['Type', 'State', 'N', 'Full', 'noGL p50', 'CPU p50/p95/p99', 'GPU timeline p50',
       'Quads', 'Flush requests', 'Draws', 'Blend switches', 'Texture binds', 'Scissor', 'B/packet'], rows)

output += [f'## {latest.name}: full HUD actor', '']
table(['Window', 'Scene', 'Candidate', 'Quads', 'Flush requests', 'Draws', 'Blend', 'Textures', 'Scissor'],
      [(r['scope'], r['type'], r['variant'], r['quads'], r['flush-requests'], r['gl-draws'],
        r['gl-blend-functions'], r['gl-texture-binds'], r['gl-scissors']) for r in counts if r['scope'].startswith('HUD')])

for name in ('run-6', 'run-7'):
    run = HERE / name
    if not (run / 'frames.csv').exists():
        continue
    output += [f'## {name}: corrected frame control', '',
               'Native commandMode stays true. Mode 0 suppresses HUD draw only, retaining model updates. '
               'HUD is explicitly configured; see frame-fixture.csv for representatives and actual P. '
               'Forward/reverse ranges of two 120-frame blocks, not pooled percentiles.', '']
    data = defaultdict(list)
    for r in read(run / 'frames.csv'):
        data[(r['scene'], r['mode'])].append(r)
    table(['Units', 'Mode', 'Frame p50 blocks', 'Frame p95 blocks', 'Frame p99 blocks',
           'HUD p50 blocks', 'HUD p95 blocks', 'Over 8.33 / 16.67 ms'],
          [(scene, mode, span(rows, 'p50-frame-us'), span(rows, 'p95-frame-us'), span(rows, 'p99-frame-us'),
            span(rows, 'p50-hud-us'), span(rows, 'p95-hud-us'),
            f"{sum(int(r['over-8.33ms']) for r in rows)} / {sum(int(r['over-16.67ms']) for r in rows)}")
           for (scene, mode), rows in sorted(data.items(), key=lambda x: (int(x[0][0]), int(x[0][1])))])
    summary[name] = dict(frames=read(run / 'frames.csv'), fixture=read(run / 'frame-fixture.csv'),
                         parity=read(run / 'parity.csv'))

run = HERE / 'run-8'
if (run / 'parity.csv').exists():
    rows = read(run / 'parity.csv')
    summary['run-8'] = dict(parity=rows)
    output += ['## run-8: maximum drift and custom blend proofs', '']
    grouped = defaultdict(list)
    for r in rows:
        grouped[r['variant']].append(r)
    table(['Variant', 'Cases', 'Different', 'Max RGB', 'Max alpha'],
          [(variant, len(items), sum(int(r['changed-pixels']) != 0 for r in items),
            max(int(r['max-rgb']) for r in items), max(int(r['max-alpha']) for r in items))
           for variant, items in sorted(grouped.items())])

(HERE / 'MEASUREMENTS.md').write_text('\n'.join(output), encoding='utf-8')
(HERE / 'summary.json').write_text(json.dumps(summary, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
print('Wrote MEASUREMENTS.md and summary.json; latest complete run:', latest.name)
